effect.shader:
void main(){
  vec2 uv = acScreenNorm;
  vec4 src = texture2DCv(inputImg.texture, uv);
  float a = max(src.a, 1e-4);
  vec3 c = src.rgb / a;
  vec3 g = mix(c, vec3(gmLum(c)), desat);
  g = mix(g, tint.rgb, fade);
  g *= mix(1.0, 0.65, fade);
  float d = length((uv - 0.5) * vec2(1.4, 1.0));
  g *= 1.0 - vignette * smoothstep(0.3, 0.85, d);
  vec3 col = mix(c, g, mixAmt);
  gl_FragColor = vec4(clamp(col, 0.0, 1.0) * a, a);
}
